def solve(s: str) -> str:
    # Rule 1: suffix 'ac' -> replace with 'cb'
    def rule1(t: str) -> str | None:
        if t.endswith('ac'):
            return t[:-2] + 'cb'
        return None

    # Rule 2: prefix 'bc' -> delete first two chars, append 'aa'
    def rule2(t: str) -> str | None:
        if t.startswith('bc'):
            return t[2:] + 'aa'
        return None

    # Rule 3: prefix 'cb' -> replace with 'aa', delete last char
    def rule3(t: str) -> str | None:
        if t.startswith('cb'):
            return ('aa' + t[2:])[:-1]
        return None

    # Rule 4: contains 'abc' -> replace first occurrence with 'cab'
    def rule4(t: str) -> str | None:
        idx = t.find('abc')
        if idx != -1:
            return t[:idx] + 'cab' + t[idx+3:]
        return None

    # Rule 5: even number of 'b's (>=1) -> append 'ab'
    def rule5(t: str) -> str | None:
        b_count = t.count('b')
        if b_count >= 1 and b_count % 2 == 0:
            return t + 'ab'
        return None

    rules = [rule1, rule2, rule3, rule4, rule5]
    return apply_ordered_rules(s, rules)

